files.fitrimnum.c:
/* SPDX-License-Identifier: MIT */
/* Prints FITRIM from the guest's <linux/fs.h> (pane 214). */
#include <stdio.h>
#include <linux/fs.h>
int main (void) { printf ("%#lx\n", (unsigned long) FITRIM); return 0; }

cases.setup_script:
export PYTHONDONTWRITEBYTECODE=1
H=/opt/bashos-parity/harness/helpers/system-seccomp.py
/usr/bin/gcc -O0 -o fitrimnum fitrimnum.c
[[ $(./fitrimnum) == 0xc0185879 ]] || { echo "CONTROL-FAILED FITRIM is $(./fitrimnum), table 0xc0185879"; exit 98; }
/usr/bin/rm -f fitrimnum
s=0; /usr/bin/python3 "$H" --kill ioctl:1=0xc0185879 -- /usr/bin/python3 fitrim_probe.py /tmp ok || s=$?
[[ $s == 159 ]] || { echo "CONTROL-FAILED FITRIM kill rule: status $s"; exit 98; }
/usr/bin/python3 "$H" --kill ioctl:1=0xc0185879 -- /usr/bin/true || { echo "CONTROL-FAILED kill rule hit a FITRIM-free program"; exit 98; }
